/* Presentation only. Both designs share the same calculation and private data. */
(function(){
const toggle=$('designToggle'),hero=$('wealthHero');
const shock=document.querySelector('.boardShock'),home=document.createComment('classic simulation position');shock.before(home);
let classic=false;try{classic=localStorage.getItem('family-dashboard-design')==='classic';}catch{}
function apply(){if(classic)home.after(shock);else $('modernControls').append(shock);document.body.classList.toggle('designModern',!classic);toggle.textContent=classic?'切換新版':'切換經典版';toggle.setAttribute('aria-pressed',String(classic));try{localStorage.setItem('family-dashboard-design',classic?'classic':'modern');}catch{}}
toggle.onclick=()=>{classic=!classic;apply();};apply();
const amount=n=>fmt(n),cap=n=>n===null?'無借款':pct(Math.floor(n*10000+1e-7)/100);
function paint(){
 if($('error').textContent){hero.innerHTML='';$('modernMemberHeading').innerHTML='';return;}
 const drop=Number($('drop').value)/100,total=RiskEngine.family(family),after=RiskEngine.family(family,drop),cash=family.reduce((s,m)=>s+m.data.cash,0),assets=total.stock+cash,share=assets>0?Math.max(0,Math.min(100,total.stock/assets*100)):0;
 const reviews=family.map(m=>RiskEngine.readiness(m.data,drop)),danger=reviews.filter(r=>r.tone==='danger').length;
 const points=Array.from({length:7},(_,i)=>({drop:i*.1,equity:RiskEngine.family(family,i*.1).equity}));const lo=Math.min(0,...points.map(p=>p.equity)),hi=Math.max(1,...points.map(p=>p.equity)),x=d=>32+d/.6*480,y=n=>176-(n-lo)/(hi-lo)*126;
 const path=points.map((p,i)=>(i?'L':'M')+x(p.drop)+','+y(p.equity)).join(' '),lineY=y(after.equity),lineX=x(drop),negative=total.equity<=0;
 hero.innerHTML=`<section class="wealthSurface"><div class="wealthMain"><span class="designEyebrow">FAMILY WEALTH / 家族資產總覽 <small>${esc($('date').value)}</small></span><div class="wealthLabel">家族淨資產 <span>萬元</span></div><div class="wealthNumber ${negative?'negative':''}">${amount(total.equity)}</div><div class="wealthSub">總資產 ${amount(assets)} <span>−</span> 借款 ${amount(total.debt)}</div><div class="allocationTrack" role="img" aria-label="股票占總資產${fmt(share)}%，現金占${fmt(100-share)}%"><i style="width:${share}%"></i></div><div class="allocationLegend"><span><i></i>股票 ${amount(total.stock)}</span><span><i></i>現金 ${amount(cash)}</span></div></div><div class="wealthChart"><div class="wealthChartHead"><span>下跌情境・淨資產變化</span><span class="scenarioChip">−${pct(drop*100)}</span></div><div class="scenarioValue">${amount(after.equity)} <small>萬元</small></div><svg viewBox="0 0 550 215" role="img" aria-label="全部股票同步下跌0至60%時家族淨資產變化；下跌${pct(drop*100)}後淨資產${fmt(after.equity)}萬元"><defs><linearGradient id="wealthFade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a8d5bc" stop-opacity=".25"/><stop offset="1" stop-color="#a8d5bc" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(v=>`<line x1="32" x2="512" y1="${50+v*126}" y2="${50+v*126}" stroke="#ffffff16"/>`).join('')}<line x1="32" x2="512" y1="${y(0)}" y2="${y(0)}" stroke="#ffffff35" stroke-dasharray="3 4"/><text x="16" y="${y(0)+4}" fill="#b1c4bb" font-size="10">0</text><path d="${path} L512,176 L32,176 Z" fill="url(#wealthFade)"/><path d="${path}" fill="none" stroke="#badeb1" stroke-width="2.5"/><line x1="${lineX}" x2="${lineX}" y1="42" y2="176" stroke="#ffffff65" stroke-dasharray="3 5"/><circle cx="${lineX}" cy="${lineY}" r="5" fill="#d4ecae" stroke="#193d34" stroke-width="3"/>${[0,.2,.4,.6].map(d=>`<text x="${x(d)}" y="203" fill="#b1c4bb" font-size="11" text-anchor="middle">${d===0?'目前':'−'+Math.round(d*100)+'%'}</text>`).join('')}</svg><div class="wealthChartFoot"><span class="statusDot ${danger?'dangerDot':''}"></span>${danger?danger+' 位成員在此情境仍需補資金':'此情境下，各成員現金與現股可支援'}<span>不跨成員調用</span></div></div></section>`;
 $('modernMemberHeading').innerHTML=`<div class="memberSectionHead"><div><span class="designEyebrow">MEMBER INSIGHTS</span><h3>每位成員，各自的安全邊界</h3></div><span>${family.length} 位成員 · 金額單位：萬元</span></div>`;
 [...$('memberCards').children].forEach((card,i)=>{const c=reviews[i].capacity,level=RiskReport.level(c.leverage);let insight=card.querySelector('.designRisk');if(!insight){insight=document.createElement('div');insight.className='designRisk';card.querySelector('.cardHead').after(insight);}insight.innerHTML=`<span class="riskLabel ${level.tone}"><i></i>${level.label}</span><span>曝險 <b>${c.leverage===null?'—':fmt(c.leverage)+'×'}</b></span>`;
 const capacities=card.querySelectorAll('.cardCapacity>div');[c.current,c.cashOnly,c.cash].forEach((v,j)=>{let track=document.createElement('div');track.className='capacityTrack';track.innerHTML=`<i style="width:${v===null?0:Math.max(0,Math.min(100,v*100))}%"></i>`;capacities[j].append(track);capacities[j].querySelector('b').textContent=cap(v);});});
}
const prior=render;render=function(){prior();paint();};$('date').addEventListener('change',paint);paint();
})();
